<template><view class="shop-page"><BusinessPageHeader title="会员信息"/><view class="shop-body"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="data"><view class="shop-card"><view class="shop-title">{{data.member.name}} <text class="shop-tag">{{data.member.badge}}</text></view><text class="shop-muted">ID：{{data.member.displayId}}　年级：{{data.member.gradeLabel}}　性别：{{data.member.genderLabel}}</text><view class="shop-card" style="background:#454b6b;margin-top:1em"><view class="shop-title">陪练卡</view><view>训练：共{{data.member.trainingTotal}}时，已消耗{{data.member.trainingUsed}}时，剩余{{data.member.trainingTotal-data.member.trainingUsed}}时</view><view>特训：共{{data.member.specialTotal}}时，已消耗{{data.member.specialUsed}}时，剩余{{data.member.specialTotal-data.member.specialUsed}}时</view><button class="shop-link" @click="feedback('training')">陪练反馈</button></view><view v-for="field in noteFields" :key="field.key" class="shop-row"><view><text class="shop-muted">{{field.label}}</text><view>{{data.member[field.key]||'暂无备注'}}</view></view><button v-if="field.kind" class="shop-link" @click="feedback(field.kind)">反馈</button></view><view class="shop-options"><button v-if="can('edit-training')" @click="edit">编辑资料 / 课时</button><button v-if="can('read-orders')" @click="orders">查看订单</button><button v-if="can('transfer')" @click="transfer">申请转店</button></view></view><view v-if="editor" class="shop-card"><view class="shop-title">编辑会员资料</view><view v-for="field in hourFields" :key="field.key"><text>{{field.label}}</text><input v-model="draft[field.key]" type="number" class="shop-field" maxlength="5"/></view><view v-for="field in noteFields" :key="field.key"><text>{{field.label}}</text><textarea v-model="draft[field.key]" class="shop-field" maxlength="500" auto-height/></view><text class="shop-error">{{actionError}}</text><view class="shop-options"><button :disabled="busy" @click="editor=false">取消</button><button :disabled="busy" @click="save">保存</button></view></view></template></view></view></template>
<script setup>
import {ref} from 'vue'
import {onLoad,onShow,onUnload} from '@dcloudio/uni-app'
import {useAuth} from '../../composables/useAuth'
import {useAsyncPage} from '../../composables/useAsyncPage'
import {getStoreMember,updateStoreMember} from '../../services/training'
import BusinessPageHeader from '../../components/BusinessPageHeader.vue'
import FeaturePageState from '../../components/FeaturePageState.vue'
useAuth();let contextId='',memberId='',active=true;const editor=ref(false),busy=ref(false),draft=ref({}),actionError=ref(''),{data,status,error,load}=useAsyncPage(()=>getStoreMember(contextId,memberId),false),noteFields=[{key:'selfStudyNote',label:'智习室',kind:'self-study'},{key:'campNote',label:'集训营',kind:'camp'},{key:'remark',label:'备注'}],hourFields=[{key:'trainingTotal',label:'训练总课时'},{key:'trainingUsed',label:'训练已消耗'},{key:'specialTotal',label:'特训总课时'},{key:'specialUsed',label:'特训已消耗'}],can=x=>data.value?.allowedActions.includes(x)
function edit(){draft.value={...data.value.member};editor.value=true;actionError.value=''}
async function save(){if(busy.value)return;busy.value=true;try{const value={version:draft.value.version};for(const f of hourFields)value[f.key]=Number(draft.value[f.key]);for(const f of noteFields)value[f.key]=draft.value[f.key];await updateStoreMember(contextId,memberId,value);if(active){editor.value=false;await load();uni.showToast({title:'已保存',icon:'success'})}}catch(e){if(active)actionError.value=e.message}finally{if(active)busy.value=false}}
const query=()=>`contextId=${encodeURIComponent(contextId)}&memberId=${encodeURIComponent(memberId)}`
function feedback(kind){uni.navigateTo({url:`/pages/feedback/list?${query()}&kind=${kind}`})}
function orders(){uni.navigateTo({url:`/pages/order/list?${query()}`})}
function transfer(){uni.navigateTo({url:`/pages/store/transfer-apply?${query()}`})}
onLoad(q=>{contextId=q.contextId||'';memberId=q.memberId||''});onShow(()=>{if(!editor.value)load()});onUnload(()=>{active=false})
</script><style>@import '../../styles/commerce.css';</style>
